
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_lieb_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_lieb", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.575944979468125e+01, 9.210234569477879e+01, 8.710172190534516e+01, 8.041353410141771e+01, 7.174699536643622e+01, 6.101292769768412e+01, 4.854426025803754e+01, 3.531318467350017e+01, 2.292967437453559e+01, 1.307308289611845e+01, 6.195020902024233e+00, 2.619058008408610e+00, 1.929789695334547e+00, 1.308887690532322e+00, 7.016794045057517e-01, 3.236779085092719e-01, 1.692609012377003e-01, 1.247217791250523e-01, 1.123870943223817e-01, 1.067791898568714e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


